-- Offres d'exemple : une par catégorie qui n'en avait pas. Rejouable sans doublon (adresse du produit unique).
DO $$ DECLARE pid uuid; did uuid; admin uuid; BEGIN
SELECT u.id INTO admin FROM users u JOIN user_roles r ON r.user_id = u.id AND r.role_code = 'SUPER_ADMIN' ORDER BY u.created_at LIMIT 1;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'ciment-50-kg') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'materiaux-construction'), 'ciment-50-kg', 'Ciment — sac de 50 kg', 'Achetez votre ciment à prix groupé grâce à GROUPIREX. Réunissez-vous avec d’autres acheteurs pour bénéficier d’un prix avantageux sur vos achats de matériaux de construction. Prix : 4 200 FCFA le sac de 50 kg. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Vendu au sac de 50 kg", "Prix groupé : 4 200 FCFA le sac", "Retrait au bureau GROUPDEALS de votre ville"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 3800, 'XAF', NULL, true, '{"en": {"name": "Cement — 50 kg bag", "description": "Buy your cement at a group price with GROUPIREX. Join other buyers to get a better price on your building materials. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'ciment-50-kg-2026-10', 'ACHAT GROUPÉ DE CIMENT — 50 KG', 'PUBLISHED', 3800, 'XAF', NULL, 2000, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'riz-25-kg') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'agro-alimentaire'), 'riz-25-kg', 'Riz de consommation — sac de 25 kg', 'Réduisez le coût de vos achats alimentaires en participant à une commande collective de riz. Plus les acheteurs se regroupent, plus GROUPIREX peut faciliter l’accès à des offres négociées. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Vendu au sac de 25 kg", "Prix indicatif, à confirmer", "Retrait au bureau GROUPDEALS de votre ville"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 13500, 'XAF', NULL, true, '{"en": {"name": "Rice — 25 kg bag", "description": "Cut the cost of your food shopping by joining a group order of rice. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'riz-25-kg-2026-10', 'ACHAT GROUPÉ DE RIZ — SAC DE 25 KG', 'PUBLISHED', 13500, 'XAF', NULL, 1000, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'abonnement-footax') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'abonnements'), 'abonnement-footax', 'Abonnement FOOTAX', 'Profitez d’une offre spéciale d’achat groupé pour votre abonnement à FOOTAX, la plateforme qui permet aux footballeurs de présenter leurs talents, de publier leurs vidéos et de découvrir des opportunités auprès des clubs et recruteurs. 20 USD au lieu de 50 USD : 30 USD d’économie, soit 60 % de réduction. Offre de démonstration, en attente de la validation des conditions de vente avec FOOTAX.', '["20 USD au lieu de 50 USD", "30 USD d’économie (−60 %)", "Service en ligne : aucun frais de livraison"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 2000, 'USD', 5000, true, '{"en": {"name": "FOOTAX subscription", "description": "Special group-buying offer on your FOOTAX subscription, the platform where footballers showcase their talent, post videos and find opportunities with clubs and scouts. 20 USD instead of 50 USD. Demo offer, pending validation of terms with FOOTAX."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'abonnement-footax-2026-10', 'ABONNEMENT FOOTAX À 20 $ AU LIEU DE 50 $', 'PUBLISHED', 2000, 'USD', 5000, 500, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'ventilateur-sur-pied') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'electromenager'), 'ventilateur-sur-pied', 'Ventilateur électrique sur pied', 'Équipez votre maison à prix avantageux en rejoignant un achat groupé de ventilateurs. La commande collective permet de réunir les besoins de plusieurs acheteurs afin de rechercher de meilleures conditions d’achat. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Ventilateur domestique sur pied", "Prix indicatif, à confirmer", "Retrait au bureau GROUPDEALS de votre ville"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 16500, 'XAF', NULL, true, '{"en": {"name": "Standing electric fan", "description": "Equip your home at a better price by joining a group purchase of fans. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'ventilateur-sur-pied-2026-10', 'ACHAT GROUPÉ DE VENTILATEURS', 'PUBLISHED', 16500, 'XAF', NULL, 300, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'chaise-de-reception') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'meubles'), 'chaise-de-reception', 'Chaise de réception empilable', 'Chaises empilables pour salles de fête, églises, restaurants et événements. En regroupant les commandes, GROUPIREX recherche de meilleures conditions d’achat. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Empilable", "Pour salles, restaurants et événements", "Prix indicatif, à confirmer"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 8500, 'XAF', NULL, true, '{"en": {"name": "Stackable banquet chair", "description": "Stackable chairs for halls, churches, restaurants and events. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'chaise-de-reception-2026-10', 'ACHAT GROUPÉ DE CHAISES DE RÉCEPTION', 'PUBLISHED', 8500, 'XAF', NULL, 500, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'casque-moto') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'auto-motos'), 'casque-moto', 'Casque de moto intégral', 'Casques intégraux pour conducteurs de moto et de taxi-moto. Rejoignez l’achat groupé pour rouler protégé à meilleur prix. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Casque intégral avec visière", "Pour motos et taxis-motos", "Prix indicatif, à confirmer"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 11500, 'XAF', NULL, true, '{"en": {"name": "Full-face motorcycle helmet", "description": "Full-face helmets for motorcycle and moto-taxi riders. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'casque-moto-2026-10', 'ACHAT GROUPÉ DE CASQUES DE MOTO', 'PUBLISHED', 11500, 'XAF', NULL, 300, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'smartphone-android-128-go') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'electronique'), 'smartphone-android-128-go', 'Smartphone Android 128 Go', 'Smartphones Android avec 128 Go de stockage, pour la famille ou pour équiper une équipe. Le regroupement des commandes permet de rechercher de meilleures conditions d’achat. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Android, 128 Go de stockage", "Pour particuliers et entreprises", "Prix indicatif, à confirmer"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 53000, 'XAF', NULL, true, '{"en": {"name": "Android smartphone, 128 GB", "description": "Android smartphones with 128 GB of storage. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'smartphone-android-128-go-2026-10', 'ACHAT GROUPÉ DE SMARTPHONES', 'PUBLISHED', 53000, 'XAF', NULL, 200, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'perruque-cheveux-naturels') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'extensions'), 'perruque-cheveux-naturels', 'Perruque cheveux longs', 'Perruques à cheveux longs pour les salons de coiffure et les particulières. En achetant à plusieurs, GROUPIREX recherche de meilleures conditions auprès des fabricants. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Cheveux longs", "Pour salons et particulières", "Prix indicatif, à confirmer"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 21000, 'XAF', NULL, true, '{"en": {"name": "Long-hair wig", "description": "Long-hair wigs for hair salons and individuals. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'perruque-cheveux-naturels-2026-10', 'ACHAT GROUPÉ DE PERRUQUES', 'PUBLISHED', 21000, 'XAF', NULL, 300, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
IF NOT EXISTS (SELECT 1 FROM products WHERE slug = 'liquide-vaisselle-5-l') THEN
  VALUES ((SELECT id FROM categories WHERE slug = 'menage'), 'liquide-vaisselle-5-l', 'Liquide vaisselle — bidon de 5 L', 'Liquide vaisselle en bidon de 5 litres pour la maison, les restaurants et les bureaux. Achetez en groupe pour réduire le coût de vos produits d’entretien. Prix indicatif de démonstration, modifiable par l’administrateur ; il sera confirmé avec le fournisseur avant toute commande.', '["Bidon de 5 litres", "Pour maison, restaurants et bureaux", "Prix indicatif, à confirmer"]'::jsonb, '[]'::jsonb, 'UNIT', 1, 1, 2500, 'XAF', NULL, true, '{"en": {"name": "Dishwashing liquid — 5 L can", "description": "Dishwashing liquid in 5-litre cans for homes, restaurants and offices. Indicative demo price, editable by the administrator."}}'::jsonb, admin) RETURNING id INTO pid;
  VALUES (pid, 'liquide-vaisselle-5-l-2026-10', 'ACHAT GROUPÉ DE LIQUIDE VAISSELLE', 'PUBLISHED', 2500, 'XAF', NULL, 1000, 1, now(), now() + interval '30 days', false, admin) RETURNING id INTO did;
END IF;
END $$;